import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.B5xlWq8G.js";const k=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1792764473000}'),o={name:"guide/faq.md"};function r(d,e,n,l,p,h){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="为什么按钮没有样式" tabindex="-1">为什么按钮没有样式？ <a class="header-anchor" href="#为什么按钮没有样式" aria-label="Permalink to &quot;为什么按钮没有样式？&quot;">​</a></h2><p>Vite / Webpack 等浏览器构建会自动引入样式。直接通过 CDN 使用 UMD 脚本时，需要同时引入 Viewer.js 的 CSS，见快速上手中的浏览器全局示例。</p><h2 id="如何用缩略图预览原图" tabindex="-1">如何用缩略图预览原图？ <a class="header-anchor" href="#如何用缩略图预览原图" aria-label="Permalink to &quot;如何用缩略图预览原图？&quot;">​</a></h2><p>组件使用 <code>url=&quot;data-source&quot;</code>；指令和 API 将 <code>options.url</code> 设置为 <code>data-source</code>，读取图片上的原图地址。</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;thumb.jpg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;large.jpg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><h2 id="如何从旧版本迁移" tabindex="-1">如何从旧版本迁移？ <a class="header-anchor" href="#如何从旧版本迁移" aria-label="Permalink to &quot;如何从旧版本迁移？&quot;">​</a></h2><p>默认插件改为局部引入：component 改为 Viewer，directive() 改为 vViewer，api 改为 useViewer，通过配置对象传入 images 和 options，并自动管理生命周期。旧的 Viewer 类改名为 ViewerJs。</p><p>组件的 <code>options</code> 保留兼容但不推荐使用，迁移为直接属性、Vue 事件和 ref 方法的示例见<a href="./component#migration">组件迁移说明</a>。</p><p><code>inited</code> 事件已移除，改为通过组件 ref 调用方法，如 <code>gallery.value.show()</code>。</p><p>组件的 <code>images</code> 和 <code>trigger</code> 属性也已移除，图片由插槽渲染并自动监听 DOM 变化；只传图片数组时使用 <code>useViewer({ images })</code>。</p>',11)])])}const u=a(o,[["render",r]]);export{k as __pageData,u as default};
